import{_ as i,o as a,a as e,b as l}from"./app.DKoEZOcr.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"HCCL通信类","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_communication"},{"text":"HCCL Tiling侧接口","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/HCCL_Tiling"},{"text":"HCCL Tiling使用说明","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/HCCL_Tiling_usage"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/HCCL_Tiling_usage.md","filePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/HCCL_Tiling_usage.md","lastUpdated":1787050286000}'),n={name:"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/HCCL_Tiling_usage.md"};function c(d,t,o,p,g,h){return a(),e("div",null,[...t[0]||(t[0]=[l(`<div><article class="markdown-body"><h1>HCCL Tiling使用说明</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本章节详述通信算子必需的TilingData结构体。本章节提供了三个版本的TilingData，建议使用<a href="TilingData_struct.html">TilingData结构体</a>，不推荐使用<a href="v1_TilingData_deprecated.html">v1版本TilingData（废弃）</a>和<a href="v2_TilingData_deprecated.html">v2版本TilingData（废弃）</a>。 对于<a href="TilingData_struct.html">TilingData结构体</a>，在定义通算融合算子的Tiling结构体时，<a href="TilingData_struct.html#table4835205712588">Mc2InitTiling</a>必须定义为算子Tiling结构体的第一个参数，<a href="TilingData_struct.html#table678914014562">Mc2CcTiling</a>对于在算子Tiling结构体中被定义的位置没有要求。</p></div><p>Ascend C提供一组HCCL Tiling API，方便用户获取HCCL核函数（Kernel）计算时所需的Tiling参数。您只需要传入通信的相关信息，调用API接口，即可获取通信相关的Tiling参数。</p><p>HCCL Tiling API获取Tiling参数的流程如下：</p><ol><li><p>创建一个<a href="HCCL_Tiling_constructor.html">Mc2CcTilingConfig</a>类对象。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>const char* groupName = &quot;testGroup&quot;;
uint32_t opType = HCCL_CMD_REDUCE_SCATTER;
std::string algConfig = &quot;ReduceScatter=level0:fullmesh&quot;;
uint32_t reduceType = HCCL_REDUCE_SUM;
AscendC::Mc2CcTilingConfig mc2CcTilingConfig(groupName, opType, algConfig, reduceType);
</code></pre></div></li><li><p>通过配置接口设置通信信息（可选）。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mc2CcTilingConfig.SetSkipLocalRankCopy(0);
mc2CcTilingConfig.SetSkipBufferWindowCopy(1);
</code></pre></div><p>可调用的配置接口列于下表。</p><p><strong>表1</strong> Mc2CcTilingConfig类对象的配置接口列表</p><table><thead><tr><th>接口</th><th>功能</th></tr></thead><tbody><tr><td><a href="SetOpType.html">SetOpType</a></td><td>设置通信任务类型。</td></tr><tr><td><a href="SetGroupName.html">SetGroupName</a></td><td>设置通信任务所在的通信域。</td></tr><tr><td><a href="SetAlgConfig.html">SetAlgConfig</a></td><td>设置通信算法。</td></tr><tr><td><a href="SetReduceType.html">SetReduceType</a></td><td>设置Reduce操作类型。</td></tr><tr><td><a href="SetStepSize.html">SetStepSize</a></td><td>设置细粒度通信时，通信算法的步长。</td></tr><tr><td><a href="SetSkipLocalRankCopy.html">SetSkipLocalRankCopy</a></td><td>设置本卡的通信算法的计算结果是否输出到recvBuf。</td></tr><tr><td><a href="SetSkipBufferWindowCopy.html">SetSkipBufferWindowCopy</a></td><td>设置通信算法获取输入数据的位置。</td></tr><tr><td><a href="SetDebugMode.html">SetDebugMode</a></td><td>设置调测模式。</td></tr></tbody></table></li><li><p>调用<a href="GetTiling.html">GetTiling</a>接口，获取Tiling信息。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mc2CcTilingConfig.GetTiling(tiling-&gt;mc2InitTiling); // tiling为算子组装的TilingData结构体
mc2CcTilingConfig.GetTiling(tiling-&gt;reduceScatterTiling);
</code></pre></div></li></ol></article></div>`,1)])])}const s=i(n,[["render",c]]);export{r as __pageData,s as default};
